#[tokio::test]
async fn t_ac_02_multi_file_kubeconfig_is_merged_from_real_files() {
    let dir = tempfile::tempdir().expect("temporary kubeconfig directory");
    let first = dir.path().join("context.yaml");
    let second = dir.path().join("cluster.yaml");
    std::fs::write(&first, "apiVersion: v1\nkind: Config\ncurrent-context: fixture\ncontexts:\n- name: fixture\n  context:\n    cluster: fixture\n    namespace: restricted\n").expect("write context");
    std::fs::write(&second, "apiVersion: v1\nkind: Config\nclusters:\n- name: fixture\n  cluster:\n    server: http://127.0.0.1:12345\n").expect("write cluster");
    let paths = std::env::join_paths([first, second]).expect("platform path list");

    let config = build_config(KubeconfigSource::Env(paths.into()), None, None)
        .await
        .expect("merge real kubeconfigs");

    assert_eq!(config.default_namespace, "restricted");
    assert_eq!(config.cluster_url.to_string(), "http://127.0.0.1:12345/");
}

