#[tokio::test]
async fn t_ac_02_list_failures_partial_success_and_recovery() {
    use std::sync::atomic::{AtomicU8, Ordering};
    let state = Arc::new(AtomicU8::new(0));
    let mode = state.clone();
    let server = crate::docker_engine::test_support::serve(move |path| {
        let state = mode.load(Ordering::SeqCst);
        async move {
            let kind = if path.contains("/pods") { "PodList" } else if path.contains("/nodes") { "NodeList" } else { "DeploymentList" };
            if state == 0 || state == 2 || (state == 3 && kind != "PodList") {
                (403, serde_json::json!({"kind":"Status", "apiVersion":"v1", "status":"Failure", "reason":"Forbidden", "message":"fixture denied", "code":403}).to_string())
            } else {
                (200, serde_json::json!({"apiVersion": if kind == "DeploymentList" { "apps/v1" } else { "v1" }, "kind":kind,"metadata":{},"items":[{"metadata":{"name":"fixture","namespace":"default"}}]}).to_string())
            }
        }
    }).await;
    let client = Client::try_from(Config::new(server.url.parse().expect("fixture URL")))
        .expect("fixture client");
    let engine = KubeEngine::new_for_test(
        ClusterKind::Generic,
        None,
        String::new(),
        ResourceCache::default(),
        MetricsCache::default(),
    );
    let pods = Api::<Pod>::all(client.clone());
    let nodes = Api::<Node>::all(client.clone());
    let deployments = Api::<Deployment>::all(client);
    let lp = ListParams::default();

    tick_resources(
        &pods,
        &nodes,
        &deployments,
        &lp,
        &engine.resources,
        &engine.scope,
        0,
    )
    .await;
    assert!(
        !engine
            .snapshot()
            .await
            .expect("initial failure snapshot")
            .reachable
    );
    assert_eq!(engine.resources.read().await.last_update_ms, 0);
    state.store(1, Ordering::SeqCst);
    tick_resources(
        &pods,
        &nodes,
        &deployments,
        &lp,
        &engine.resources,
        &engine.scope,
        0,
    )
    .await;
    assert!(engine.snapshot().await.expect("healthy snapshot").reachable);
    let last_success = engine.resources.read().await.last_update_ms;
    state.store(2, Ordering::SeqCst);
    tick_resources(
        &pods,
        &nodes,
        &deployments,
        &lp,
        &engine.resources,
        &engine.scope,
        0,
    )
    .await;
    assert!(!engine.snapshot().await.expect("outage snapshot").reachable);
    assert_eq!(engine.resources.read().await.last_update_ms, last_success);
    state.store(3, Ordering::SeqCst);
    tick_resources(
        &pods,
        &nodes,
        &deployments,
        &lp,
        &engine.resources,
        &engine.scope,
        0,
    )
    .await;
    let partial = engine.snapshot().await.expect("restricted RBAC snapshot");
    assert!(partial.reachable);
    assert_eq!(partial.pods.len(), 1, "permitted resources stay usable");
    assert!(
        partial.nodes.is_empty(),
        "denied resources must not retain live-looking rows"
    );
    assert!(partial.deployments.is_empty());
    assert!(!partial.metrics_available);
    assert_eq!(
        engine.resources.read().await.poll_state,
        Some(ResourcePollState::Partial)
    );
    state.store(1, Ordering::SeqCst);
    tick_resources(
        &pods,
        &nodes,
        &deployments,
        &lp,
        &engine.resources,
        &engine.scope,
        0,
    )
    .await;
    assert!(
        engine
            .snapshot()
            .await
            .expect("recovered snapshot")
            .reachable
    );
    assert_eq!(
        engine.resources.read().await.poll_state,
        Some(ResourcePollState::Complete)
    );
    tokio::time::pause();
    tokio::time::advance(POLL_INTERVAL * 4).await;
    assert!(matches!(
        engine.snapshot().await,
        Err(ClusterError::Stale { .. })
    ));
    tokio::time::resume();
    tick_resources(
        &pods,
        &nodes,
        &deployments,
        &lp,
        &engine.resources,
        &engine.scope,
        0,
    )
    .await;
    assert!(
        engine
            .snapshot()
            .await
            .expect("recovery after stale cache")
            .reachable
    );
}

#[tokio::test]
async fn t_ac_02_delayed_old_scope_cannot_publish_resources() {
    let requested = Arc::new(tokio::sync::Notify::new());
    let release = Arc::new(tokio::sync::Notify::new());
    let seen = requested.clone();
    let gate = release.clone();
    let server = crate::docker_engine::test_support::serve(move |path| {
        let seen = seen.clone();
        let gate = gate.clone();
        async move {
            if path.contains("/pods") {
                seen.notify_one();
                gate.notified().await;
                (200, serde_json::json!({"apiVersion":"v1","kind":"PodList","metadata":{},"items":[{"metadata":{"name":"old-pod","namespace":"old"}}]}).to_string())
            } else {
                let (api, kind) = if path.contains("/nodes") { ("v1", "NodeList") } else { ("apps/v1", "DeploymentList") };
                (200, serde_json::json!({"apiVersion":api,"kind":kind,"metadata":{},"items":[]}).to_string())
            }
        }
    }).await;
    let client = Client::try_from(Config::new(server.url.parse().expect("fixture URL")))
        .expect("fixture client");
    let engine = KubeEngine::new_for_test(
        ClusterKind::Generic,
        None,
        "old".into(),
        ResourceCache::default(),
        MetricsCache::default(),
    );
    let cache = engine.resources.clone();
    let scope = engine.scope.clone();
    let handle = tokio::spawn(async move {
        tick_resources(
            &Api::<Pod>::namespaced(client.clone(), "old"),
            &Api::<Node>::all(client.clone()),
            &Api::<Deployment>::namespaced(client, "old"),
            &ListParams::default(),
            &cache,
            &scope,
            0,
        )
        .await;
    });
    requested.notified().await;
    engine.set_scope(KubeScope::Namespace("new".into())).await;
    release.notify_one();
    handle.await.expect("delayed collection completed");

    let snapshot = engine.snapshot().await.expect("rescoped snapshot");
    assert_eq!(snapshot.current_namespace, "new");
    assert!(
        snapshot.pods.is_empty(),
        "old namespace leaked through a delayed LIST"
    );
}

#[tokio::test]
async fn t_ac_02_delayed_old_scope_cannot_publish_metrics() {
    let requested = Arc::new(tokio::sync::Notify::new());
    let release = Arc::new(tokio::sync::Notify::new());
    let seen = requested.clone();
    let gate = release.clone();
    let server = crate::docker_engine::test_support::serve(move |path| {
        let seen = seen.clone();
        let gate = gate.clone();
        async move {
            if path.contains("/pods") {
                seen.notify_one();
                gate.notified().await;
                (200, serde_json::json!({"items":[{"metadata":{"name":"old-pod","namespace":"old"},"containers":[{"usage":{"cpu":"100m","memory":"1Mi"}}]}]}).to_string())
            } else { (200, "{\"items\":[]}".into()) }
        }
    }).await;
    let client = Client::try_from(Config::new(server.url.parse().expect("fixture URL")))
        .expect("fixture client");
    let engine = KubeEngine::new_for_test(
        ClusterKind::Generic,
        None,
        "old".into(),
        ResourceCache::default(),
        MetricsCache::default(),
    );
    let cache = engine.metrics.clone();
    let scope = engine.scope.clone();
    let handle = tokio::spawn(async move {
        tick_metrics(
            &client,
            &cache,
            &KubeScope::Namespace("old".into()),
            &scope,
            0,
        )
        .await;
    });
    requested.notified().await;
    engine.set_scope(KubeScope::Namespace("new".into())).await;
    release.notify_one();
    handle.await.expect("delayed metrics completed");

    assert!(
        !engine.metrics_available().await,
        "old metrics advertised under new scope"
    );
    assert!(engine.metrics.read().await.pods.is_empty());
}
